import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema registration [specs/hal-engine-tool-input-validation/spec.md#5]', () => {
  it('rejects an invalid static schema when registering the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Weather lookup',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });
});

describe('ToolRegistry dynamic schema validation [specs/hal-engine-tool-input-validation/spec.md#7]', () => {
  it('caches dynamic validators by schema identity', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const registry = new ToolRegistry();
      const locationSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
      const unitsSchema = {type: 'object', properties: {units: {type: 'string'}}, required: ['units']};
      let activeSchema: typeof locationSchema | typeof unitsSchema = locationSchema;
      let executeCalls = 0;
      registry.register(
        () => ({name: 'weather', description: 'Weather lookup', inputSchema: activeSchema}),
        async () => {
          executeCalls += 1;
          return 'sunny';
        }
      );

      const first = await registry.execute('weather', {});
      activeSchema = unitsSchema;
      const second = await registry.execute('weather', {});
      activeSchema = locationSchema;
      const third = await registry.execute('weather', {location: 'Berlin'});

      expect({
        first: first.result,
        second: second.result,
        third: third.result,
        executeCalls,
        compileCalls: compile.mock.calls.length,
      }).toEqual({
        first: expect.stringContaining('location'),
        second: expect.stringContaining('units'),
        third: 'sunny',
        executeCalls: 1,
        compileCalls: 2,
      });
    } finally {
      compile.mockRestore();
    }
  });
});

describe('ToolRegistry wrong-typed input [specs/hal-engine-tool-input-validation/spec.md#2]', () => {
  it('reports a property name containing a slash as the failing field path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a record',
        inputSchema: {type: 'object', properties: {'user/name': {type: 'string'}}},
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup', {'user/name': 123456789});

    expect(response.result).toContain('input.user/name must be string');
  });
});

describe('ToolRegistry required input [specs/hal-engine-tool-input-validation/spec.md#1]', () => {
  it('reports a required property name containing a slash as the failing field path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a record',
        inputSchema: {type: 'object', properties: {'user/name': {type: 'string'}}, required: ['user/name']},
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup', {});

    expect(response.result).toContain('input.user/name must satisfy required');
  });
});

describe('ToolRegistry input validation [specs/hal-engine-tool-input-validation/spec.md#1]', () => {
  it('rejects a missing required field before calling the executor', async () => {
    const registry = new ToolRegistry();
    let executeCalls = 0;
    const execute = async () => {
      executeCalls += 1;
      return 'sunny';
    };
    registry.register(
      {
        name: 'weather',
        description: 'Weather lookup',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      execute
    );

    const response = await registry.execute('weather', {});

    expect({result: response.result, executeCalls}).toEqual({
      result: expect.stringMatching(/location.*required|required.*location/i),
      executeCalls: 0,
    });
  });
});

describe('ToolRegistry enum validation [specs/hal-engine-tool-input-validation/spec.md#4]', () => {
  it('lists permitted enum values without echoing the rejected value', async () => {
    const registry = new ToolRegistry();
    let executeCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Weather lookup',
        inputSchema: {type: 'object', properties: {units: {type: 'string', enum: ['metric', 'imperial']}}},
      },
      async () => {
        executeCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {units: 'private-choice-123'});

    expect({result: response.result, executeCalls}).toEqual({
      result: 'Invalid tool input: input.units must be one of metric, imperial',
      executeCalls: 0,
    });
  });
});

import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(tool: StoredTool): ValidateFunction {
    if (tool.validator) return tool.validator;
    const schema = this.resolveDefinition(tool.definitionSource).inputSchema;
    let validator = this.dynamicValidators.get(schema);
    if (!validator) {
      validator = this.ajv.compile(schema);
      this.dynamicValidators.set(schema, validator);
    }
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid input schema for tool ${resolved.name}: ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input before execution; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator = this.validatorFor(tool);
    if (!validator(input)) {
      const failures =
        validator.errors?.map(error => {
          const instancePath = 'instancePath' in error ? String(error.instancePath) : '';
          const dataPath = 'dataPath' in error ? String(error.dataPath) : '';
          const missingProperty = 'missingProperty' in error.params ? String(error.params.missingProperty) : '';
          const escapedProperty = missingProperty.replaceAll('~', '~0').replaceAll('/', '~1');
          const field = error.keyword === 'required' ? `${instancePath}/${escapedProperty}` : instancePath;
          const path = field
            ? `input.${field
                .split('/')
                .slice(1)
                .map(segment => segment.replace(/~1/g, '/').replace(/~0/g, '~'))
                .join('.')}`
            : `input${dataPath.replace(/\[['"]([^'"]+)['"]\]/g, '.$1')}`;
          let constraint = `must satisfy ${error.keyword}`;
          if (error.keyword === 'type' && 'type' in error.params) {
            constraint = `must be ${String(error.params.type)}`;
          } else if (
            error.keyword === 'enum' &&
            'allowedValues' in error.params &&
            Array.isArray(error.params.allowedValues)
          ) {
            constraint = `must be one of ${error.params.allowedValues.map(String).join(', ')}`;
          }
          return `${path} ${constraint}`;
        }) ?? [];
      const result = `Invalid tool input: ${failures.join('; ')}`;
      log.warn('tool', 'input rejected', {name, failures});
      return {result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

#!/usr/bin/env node
// Holds every `([validated by: <test name>](path#Lnn))` citation to the test it names.
//
// Usage:
//   node scripts/check-spec-anchor-names.mjs           # report, exit 1 on any finding
//   node scripts/check-spec-anchor-names.mjs --fix     # repoint each line from the name it carries
//
// A line number is the wrong thing to cite: inserting an import above a suite moves every test below
// it, and the citation silently lands on a different, still-valid declaration. The name is what the
// author meant, so the name is what the citation records and the line becomes a derived pointer this
// script repairs. The `#Lnn` stays because the lint rule and the coverage job both index by it, and a
// citation without one marks the whole file covered rather than one test.
import {readFileSync, writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import process from 'node:process';
import {dirname, join, normalize} from 'node:path';
import {root} from './lib/repo-root.mjs';

const CITATION = /\[validated by(?<label>: [^\]]*)?\]\((?<path>(?:\.\.\/)+[\w./-]+?)#L(?<line>\d+)\)/g;
// Any other href shape is refused rather than ignored: the coverage job resolves `./../x` and `/x`
// to the same file and counts them, while this gate and the drift check would never have read them.
const ANY_HREF = /\[validated by(?:: [^\]]*)?\]\((?<path>[^)#\s]+)#L\d+\)/g;
// `xit`, `xdescribe` and `.skip` declare a test that never runs, which validates nothing.
const DECLARATION = /^\s*(?:f?it|f?describe|test)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const SKIPPED = /^\s*(?:x(?:it|describe|test)|(?:it|describe|test)\.skip)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;

const cache = new Map();
const args = process.argv.slice(2);
const fix = args.includes('--fix');
const named = args.filter(arg => !arg.startsWith('--'));
const findings = [];
let checked = 0;
let repaired = 0;

for (const spec of named.length > 0 ? named : specs()) {
  const source = readFileSync(join(root, spec), 'utf8');
  const specDir = dirname(spec);
  let changed = false;

  for (const match of source.matchAll(ANY_HREF)) {
    if (!match.groups.path.startsWith('../')) {
      findings.push(`${spec}: href "${match.groups.path}" must be relative and start with ../`);
    }
  }

  const rewritten = source.replace(CITATION, (whole, label, path, line, ...rest) => {
    const groups = rest[rest.length - 1];
    const target = normalize(join(specDir, groups.path));
    if (!TEST_FILE.test(target)) return whole;

    checked += 1;
    const declarations = declarationsIn(target);
    if (declarations === null) {
      findings.push(`${spec}: ${groups.path} does not exist`);
      return whole;
    }

    const named = groups.label ? groups.label.slice(2) : null;
    const atLine = declarations.find(declaration => declaration.line === Number(groups.line));

    const skipped = declarations.find(d => d.skipped && (d.name === named || d.line === Number(groups.line)));
    if (skipped) {
      findings.push(`${spec}: cites "${skipped.name}" at ${groups.path}#L${skipped.line}, which is skipped and validates nothing`);
      return whole;
    }

    if (named === null) {
      if (!atLine) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} is not a declaration, so no name can be read from it`);
        return whole;
      }
      if (nameIsAmbiguous(declarations, atLine.name)) {
        findings.push(ambiguity(spec, groups.path, atLine.name, declarations));
        return whole;
      }
      if (!fix) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} carries no test name`);
        return whole;
      }
      return rewrite(atLine.name, groups.path, atLine.line);
    }

    // Checked before the line is consulted: a name that identifies two declarations is not an
    // identifier, and while the line happens to agree nothing would ever say so.
    if (nameIsAmbiguous(declarations, named)) {
      findings.push(ambiguity(spec, groups.path, named, declarations));
      return whole;
    }

    if (atLine && atLine.name === named) return whole;

    const [match] = declarations.filter(declaration => declaration.name === named);
    if (!match) {
      findings.push(`${spec}: names "${named}", which no declaration in ${groups.path} has`);
      return whole;
    }
    if (!fix) {
      findings.push(`${spec}: names "${named}" but points at #L${groups.line}; it is at #L${match.line}`);
      return whole;
    }
    return rewrite(named, groups.path, match.line);

    function rewrite(name, path, line) {
      // A name carrying a bracket would close the markdown label early: the citation stops being a
      // link, stops matching CITATION, and disappears from this gate and from the coverage job.
      if (/[[\]]/.test(name)) {
        findings.push(`${spec}: "${name}" carries a bracket and cannot be written into a markdown label`);
        return whole;
      }
      repaired += 1;
      changed = true;
      return citation(name, path, line);
    }
  });

  if (changed) writeFileSync(join(root, spec), rewritten);
}

for (const finding of findings) process.stderr.write(`check-spec-anchor-names: ${finding}\n`);

if (findings.length > 0) {
  process.stderr.write(`\ncheck-spec-anchor-names: ${findings.length} finding(s).\n`);
  process.stderr.write('Run `npm run spec:names -- --fix` to repoint a citation from the name it carries.\n');
  process.exit(1);
}

const verb = fix ? `repointed ${repaired},` : '';
process.stdout.write(`check-spec-anchor-names: ${verb} ${checked} citation(s) name the test they point at\n`);

function nameIsAmbiguous(declarations, name) {
  return declarations.filter(declaration => declaration.name === name && !declaration.skipped).length > 1;
}

function ambiguity(spec, path, name, declarations) {
  const lines = declarations.filter(declaration => declaration.name === name).map(d => `#L${d.line}`);
  return `${spec}: "${name}" names ${lines.length} declarations in ${path} (${lines.join(', ')}) — rename one`;
}

function citation(name, path, line) {
  return `[validated by: ${name}](${path}#L${line})`;
}

function declarationsIn(path) {
  if (cache.has(path)) return cache.get(path);

  let lines;
  try {
    lines = readFileSync(join(root, path), 'utf8').split('\n');
  } catch {
    cache.set(path, null);
    return null;
  }
  const found = lines.flatMap((text, index) => {
    const match = DECLARATION.exec(text);
    if (match) return [{line: index + 1, name: match[2], skipped: false}];
    const skipped = SKIPPED.exec(text);
    return skipped ? [{line: index + 1, name: skipped[2], skipped: true}] : [];
  });

  cache.set(path, found);
  return found;
}

function specs() {
  const out = execFileSync('git', ['ls-files', 'specs/**/*.md', 'adrs/*.md'], {cwd: root, encoding: 'utf8'});
  return out.trim().split('\n').filter(Boolean);
}

import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import {AIError} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ToolResponse} from './tools/registry.js';
import type {OutgoingMessage} from '../types/messages.js';
import type {SessionEntry} from '../types/session.js';

// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
const SENT_AT = '2026-01-01T00:00:00.000Z';

// One expect per test needs the rejection as a value rather than a matcher.
const outcomeOf = (call: Promise<unknown>): Promise<string> =>
  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string, usage?: UsageMetadata): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn', usage};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

function createErrorProvider(error: Error): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw error;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

type RecordedHook =
  | 'beforeSession'
  | 'beforeUserInput'
  | 'afterUserInput'
  | 'beforeModelResponse'
  | 'afterModelResponse'
  | 'afterSession'
  | 'onError';

// Only the named hooks are installed: one that merely exists changes the observed order.
const recordingHooks = (callOrder: string[], names: RecordedHook[]): OrchestratorHooks => {
  const all: Required<OrchestratorHooks> = {
    beforeSession: async () => void callOrder.push('beforeSession'),
    beforeUserInput: async (_session, msg) => {
      callOrder.push('beforeUserInput');
      return msg;
    },
    afterUserInput: async () => void callOrder.push('afterUserInput'),
    beforeModelResponse: async (_session, systemPrompt) => {
      callOrder.push('beforeModelResponse');
      return systemPrompt;
    },
    afterModelResponse: async () => void callOrder.push('afterModelResponse'),
    afterSession: async () => void callOrder.push('afterSession'),
    onError: async () => void callOrder.push('onError'),
  };

  return Object.fromEntries(names.map(name => [name, all[name]])) as OrchestratorHooks;
};

// Records what the orchestrator actually sent, for tests that assert on the request.
const capturingProvider = (): {provider: AIProvider; sent: {systemPrompt: string; lastUserContent: string}} => {
  const sent = {systemPrompt: '', lastUserContent: ''};

  return {
    sent,
    provider: {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        sent.systemPrompt = params.systemPrompt;
        const last = params.messages[params.messages.length - 1];
        sent.lastUserContent = typeof last.content === 'string' ? last.content : '';
        yield {type: 'text', text: 'ok'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    },
  };
};

describe('ChatOrchestrator hooks', () => {
  describe('beforeSession', () => {
    it('called before anything else', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder[0]).toBe('beforeSession');
    });
  });

  describe('afterSession', () => {
    it('called after everything completes', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['afterModelResponse', 'afterSession']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder).toEqual(['afterModelResponse', 'afterSession']);
    });

    it('called even when an error occurs', async () => {
      let afterSessionCalled = false;
      const hooks: OrchestratorHooks = {
        onError: async () => {},
        afterSession: async () => {
          afterSessionCalled = true;
        },
      };

      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
        hooks,
      });
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, afterSessionCalled}).toEqual({outcome: 'boom', afterSessionCalled: true});
    });
  });

  describe('beforeUserInput', () => {
    it('receives the last user message content', async () => {
      let receivedMessage = '';
      const hooks: OrchestratorHooks = {
        beforeUserInput: async (_session, userMessage) => {
          receivedMessage = userMessage;
          return userMessage;
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('my answer'));

      expect(receivedMessage).toBe('my answer');
    });

    it('modifies user message when returning different value', async () => {
      const {provider, sent} = capturingProvider();

      const hooks: OrchestratorHooks = {
        beforeUserInput: async (_session, _msg) => 'sanitized input',
      };

      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('raw input'));

      expect(sent.lastUserContent).toBe('sanitized input');
    });
  });

  describe('afterUserInput', () => {
    it('receives user message after any beforeUserInput modification', async () => {
      let afterReceived = '';
      const hooks: OrchestratorHooks = {
        beforeUserInput: async (_s, _msg) => 'modified',
        afterUserInput: async (_s, msg) => {
          afterReceived = msg;
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('original'));

      expect(afterReceived).toBe('modified');
    });
  });

  describe('beforeModelResponse', () => {
    it('replaces system prompt with returned value', async () => {
      const {provider, sent} = capturingProvider();

      const hooks: OrchestratorHooks = {
        beforeModelResponse: async (_session, _basePrompt) => 'Custom prompt for this question',
      };

      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(sent.systemPrompt).toBe('Custom prompt for this question');
    });
  });

  describe('afterModelResponse', () => {
    it('receives collected response text and usage', async () => {
      const usage: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
      let receivedText = '';
      let receivedUsage: UsageMetadata | undefined;

      const hooks: OrchestratorHooks = {
        afterModelResponse: async (_session, text, u) => {
          receivedText = text;
          receivedUsage = u;
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('hello world', usage), promptBuilder, undefined, {
        hooks,
      });
      await orchestrator.processMessage(createSession('hi'));

      expect({receivedText, receivedUsage}).toEqual({receivedText: 'hello world', receivedUsage: usage});
    });

    it('not called when stream throws', async () => {
      let afterCalled = false;
      const hooks: OrchestratorHooks = {
        afterModelResponse: async () => {
          afterCalled = true;
        },
        onError: async () => {},
      };

      const orchestrator = createChatOrchestrator(
        createErrorProvider(new AIError('fail', 'TEST')),
        promptBuilder,
        undefined,
        {hooks}
      );
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, afterCalled}).toEqual({outcome: 'fail', afterCalled: false});
